import { NotFoundError } from '../../domain/errors/NotFoundError';
import { UnknownAssigneeError } from '../../domain/errors/UnknownAssigneeError';
import { TaskRepository } from '../../domain/repositories/TaskRepository';
import { UserRepository } from '../../domain/repositories/UserRepository';
import { TaskDto, toTaskDto } from '../dto/TaskDto';
import { AssignTaskInput } from '../dto/TaskInputs';
import { UseCase } from '../ports/UseCase';

export class AssignTaskUseCase implements UseCase<AssignTaskInput, TaskDto> {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
  ) {}

  async execute(input: AssignTaskInput): Promise<TaskDto> {
    const task = await this.tasks.findById(input.taskId);
    if (task === undefined) {
      throw new NotFoundError('Task', input.taskId);
    }
    const user = await this.users.findById(input.userId);
    if (user === undefined) {
      throw new UnknownAssigneeError(input.userId);
    }

    task.assignTo(user);
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

