import { NotFoundError } from '../../domain/errors/NotFoundError';
import { TaskRepository } from '../../domain/repositories/TaskRepository';
import { TaskDto, toTaskDto } from '../dto/TaskDto';
import { MarkTaskDoneInput } from '../dto/TaskInputs';
import { UseCase } from '../ports/UseCase';

export class MarkTaskDoneUseCase implements UseCase<MarkTaskDoneInput, TaskDto> {
  constructor(private readonly tasks: TaskRepository) {}

  async execute(input: MarkTaskDoneInput): Promise<TaskDto> {
    const task = await this.tasks.findById(input.taskId);
    if (task === undefined) {
      throw new NotFoundError('Task', input.taskId);
    }

    task.markDone();
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

